#!/usr/bin/env bash
# Downloads a public-domain text corpus from Project Gutenberg and prepares it
# for both halves of the project: an n-gram/autocomplete training set and a
# compression benchmark input.
#
#   ./scripts/fetch_data.sh [output_dir]
#
# Nothing here is committed to the repo -- data/ is gitignored, and every file
# is regenerated by this script.
set -euo pipefail

OUT_DIR="${1:-$(cd "$(dirname "$0")/.." && pwd)/data}"
BOOKS_DIR="$OUT_DIR/books"
mkdir -p "$BOOKS_DIR"

# id:title -- all public domain (Project Gutenberg, US).
BOOKS=(
  "1342:pride-and-prejudice"
  "84:frankenstein"
  "1661:sherlock-holmes"
  "2701:moby-dick"
  "98:a-tale-of-two-cities"
  "1400:great-expectations"
  "11:alice-in-wonderland"
  "74:tom-sawyer"
  "345:dracula"
  "1260:jane-eyre"
  "174:the-picture-of-dorian-gray"
  "158:emma"
)

fetch() {
  local id="$1" dest="$2"
  for url in \
    "https://www.gutenberg.org/cache/epub/${id}/pg${id}.txt" \
    "https://www.gutenberg.org/files/${id}/${id}-0.txt" \
    "https://www.gutenberg.org/files/${id}/${id}.txt"; do
    if curl -fsSL --retry 5 --retry-all-errors --retry-delay 2 --max-time 180 -o "$dest.tmp" "$url" 2>/dev/null; then
      mv "$dest.tmp" "$dest"
      return 0
    fi
  done
  rm -f "$dest.tmp"
  return 1
}

# Project Gutenberg wraps each book in a licence header and footer; keep only
# the body so the corpus is prose rather than boilerplate.
strip_boilerplate() {
  awk '
    /^\*\*\* *START OF (THE|THIS) PROJECT GUTENBERG/ { body = 1; next }
    /^\*\*\* *END OF (THE|THIS) PROJECT GUTENBERG/   { body = 0 }
    body { print }
  ' "$1"
}

echo "Fetching ${#BOOKS[@]} public-domain books into $BOOKS_DIR"
ok=0
for entry in "${BOOKS[@]}"; do
  id="${entry%%:*}"
  name="${entry##*:}"
  raw="$BOOKS_DIR/$name.raw.txt"
  clean="$BOOKS_DIR/$name.txt"
  if [ -s "$clean" ]; then
    echo "  [cached] $name"
    ok=$((ok + 1))
    continue
  fi
  printf '  [%2d/%2d] %-28s ' "$((ok + 1))" "${#BOOKS[@]}" "$name"
  if fetch "$id" "$raw"; then
    strip_boilerplate "$raw" > "$clean"
    # Fall back to the raw file if the markers were missing or moved.
    if [ ! -s "$clean" ]; then cp "$raw" "$clean"; fi
    rm -f "$raw"
    echo "ok ($(wc -c < "$clean") bytes)"
    ok=$((ok + 1))
  else
    echo "FAILED (skipped)"
  fi
done

if [ "$ok" -eq 0 ]; then
  echo "error: could not download any book -- check network access" >&2
  exit 1
fi

cat "$BOOKS_DIR"/*.txt > "$OUT_DIR/corpus.txt"

# Hold out the last 8% of lines for evaluation so the accuracy numbers are
# measured on text the model was never trained on.
total=$(wc -l < "$OUT_DIR/corpus.txt")
test_lines=$((total * 8 / 100))
train_lines=$((total - test_lines))
head -n "$train_lines" "$OUT_DIR/corpus.txt" > "$OUT_DIR/train.txt"
tail -n "$test_lines" "$OUT_DIR/corpus.txt" > "$OUT_DIR/test.txt"

echo
echo "corpus.txt : $(wc -c < "$OUT_DIR/corpus.txt") bytes, $total lines"
echo "train.txt  : $(wc -c < "$OUT_DIR/train.txt") bytes, $train_lines lines"
echo "test.txt   : $(wc -c < "$OUT_DIR/test.txt") bytes, $test_lines lines"
echo "books      : $ok of ${#BOOKS[@]}"
